// msg.messages: an array of Kafka messages, sent in one go.
// Element: { value, key, headers, partition, timestamp, topic }
const messages = [];
for (let i = 1; i <= 1000; i++) {
    messages.push({
        key: 'sensor-' + (i % 10),
        value: { reading: i, value: Math.round(Math.random() * 1000) / 10 }
    });
}
msg.topic = 'example-batch';
msg.messages = messages;
return msg;

// Shows how many messages arrived per topic in the node status.
const counts = context.get('counts') || {};
counts[msg.topic] = (counts[msg.topic] || 0) + 1;
context.set('counts', counts);
node.status({
    fill: 'green', shape: 'dot',
    text: Object.keys(counts).map((t) => `${t}: ${counts[t]}`).join(', ')
});
return null;
